// A work-alike of CPython's `json.loads`.
//
// The value model below is what lets the rest of the port behave like Python
// rather than like JavaScript:
//
//   Python int    -> BigInt   (arbitrary precision, exactly like CPython)
//   Python float  -> Number
//   Python str    -> String
//   Python bool   -> Boolean
//   Python None   -> null
//   Python list   -> Array
//   Python dict   -> Map      (any key, insertion ordered, no __proto__ traps)
//
// Keeping int and float apart matters: `multipleOf` takes a different code path
// for a float divisor than for an int one, and big integers must compare
// exactly rather than collapsing onto a double.

export class JSONDecodeError extends Error {
  constructor(msg, doc, pos) {
    const { line, col } = lineCol(doc, pos);
    super(`${msg}: line ${line} column ${col} (char ${pos})`);
    this.name = 'JSONDecodeError';
    this.msg = msg;
    this.doc = doc;
    this.pos = pos;
    this.lineno = line;
    this.colno = col;
  }
}

function lineCol(doc, pos) {
  const upto = doc.slice(0, pos);
  const line = upto.split('\n').length;
  const col = pos - (upto.lastIndexOf('\n') + 1) + 1;
  return { line, col };
}

const WHITESPACE = ' \t\n\r';

// CPython's json.scanner.NUMBER_RE. A match with neither a fraction nor an
// exponent part is an int; anything else goes through float().
const NUMBER_RE = /(-?(?:0|[1-9]\d*))(\.\d+)?([eE][-+]?\d+)?/y;

const ESCAPES = {
  '"': '"',
  '\\': '\\',
  '/': '/',
  b: '\b',
  f: '\f',
  n: '\n',
  r: '\r',
  t: '\t',
};

class Decoder {
  constructor(text) {
    this.s = text;
    this.i = 0;
  }

  error(msg, pos = this.i) {
    throw new JSONDecodeError(msg, this.s, pos);
  }

  skipWs() {
    while (this.i < this.s.length && WHITESPACE.includes(this.s[this.i])) this.i++;
  }

  decode() {
    this.skipWs();
    const value = this.scanValue();
    this.skipWs();
    if (this.i !== this.s.length) this.error('Extra data');
    return value;
  }

  scanValue() {
    if (this.i >= this.s.length) this.error('Expecting value');
    const c = this.s[this.i];

    if (c === '"') return this.scanString();
    if (c === '{') return this.scanObject();
    if (c === '[') return this.scanArray();

    if (this.s.startsWith('null', this.i)) { this.i += 4; return null; }
    if (this.s.startsWith('true', this.i)) { this.i += 4; return true; }
    if (this.s.startsWith('false', this.i)) { this.i += 5; return false; }

    // CPython accepts these three non-standard constants by default.
    if (this.s.startsWith('NaN', this.i)) { this.i += 3; return NaN; }
    if (this.s.startsWith('Infinity', this.i)) { this.i += 8; return Infinity; }
    if (this.s.startsWith('-Infinity', this.i)) { this.i += 9; return -Infinity; }

    NUMBER_RE.lastIndex = this.i;
    const m = NUMBER_RE.exec(this.s);
    if (m && m[0] !== '') {
      this.i = NUMBER_RE.lastIndex;
      const [, intPart, frac, exp] = m;
      if (frac || exp) return Number(m[0]);
      return BigInt(intPart);
    }

    this.error('Expecting value');
  }

  scanString() {
    const s = this.s;
    let i = this.i + 1; // skip the opening quote
    let out = '';
    let chunkStart = i;

    for (;;) {
      if (i >= s.length) this.error('Unterminated string starting at', this.i);
      const c = s[i];

      if (c === '"') {
        out += s.slice(chunkStart, i);
        this.i = i + 1;
        return out;
      }

      if (c === '\\') {
        out += s.slice(chunkStart, i);
        i++;
        if (i >= s.length) this.error('Unterminated string starting at', this.i);
        const esc = s[i];

        if (esc === 'u') {
          const hex = s.slice(i + 1, i + 5);
          if (hex.length < 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) {
            this.error('Invalid \\uXXXX escape', i - 1);
          }
          let code = parseInt(hex, 16);
          i += 5;
          // CPython joins a well-formed surrogate pair into one code point;
          // a lone surrogate is kept as-is.
          if (code >= 0xd800 && code <= 0xdbff && s[i] === '\\' && s[i + 1] === 'u') {
            const hex2 = s.slice(i + 2, i + 6);
            if (/^[0-9a-fA-F]{4}$/.test(hex2)) {
              const low = parseInt(hex2, 16);
              if (low >= 0xdc00 && low <= 0xdfff) {
                code = 0x10000 + ((code - 0xd800) << 10) + (low - 0xdc00);
                i += 6;
              }
            }
          }
          out += String.fromCodePoint(code);
        } else if (Object.prototype.hasOwnProperty.call(ESCAPES, esc)) {
          out += ESCAPES[esc];
          i++;
        } else {
          this.error(`Invalid \\escape: ${JSON.stringify(esc).slice(1, -1)}`, i - 1);
        }
        chunkStart = i;
        continue;
      }

      // strict=True forbids raw control characters inside strings.
      if (c < ' ') {
        this.error(`Invalid control character ${JSON.stringify(c)} at`, i);
      }
      i++;
    }
  }

  scanArray() {
    this.i++; // '['
    const out = [];
    this.skipWs();
    if (this.s[this.i] === ']') { this.i++; return out; }

    for (;;) {
      this.skipWs();
      out.push(this.scanValue());
      this.skipWs();
      const c = this.s[this.i];
      if (c === ']') { this.i++; return out; }
      if (c !== ',') this.error("Expecting ',' delimiter");
      this.i++;
    }
  }

  scanObject() {
    this.i++; // '{'
    const out = new Map();
    this.skipWs();
    if (this.s[this.i] === '}') { this.i++; return out; }

    for (;;) {
      this.skipWs();
      if (this.s[this.i] !== '"') {
        this.error('Expecting property name enclosed in double quotes');
      }
      const key = this.scanString();
      this.skipWs();
      if (this.s[this.i] !== ':') this.error("Expecting ':' delimiter");
      this.i++;
      this.skipWs();
      // A repeated key overwrites the value but keeps its original position,
      // exactly as a Python dict does.
      out.set(key, this.scanValue());
      this.skipWs();
      const c = this.s[this.i];
      if (c === '}') { this.i++; return out; }
      if (c !== ',') this.error("Expecting ',' delimiter");
      this.i++;
    }
  }
}

export function loads(text) {
  if (typeof text !== 'string') throw new TypeError('the JSON object must be str');
  return new Decoder(text).decode();
}

