// Python value semantics on top of the representation produced by pyjson.mjs.
//
// The subtleties that actually change results:
//   * `bool` is a subclass of `int` in Python, so `True == 1` — except that
//     jsonschema deliberately defeats that at the *top* level via `unbool`.
//     Nested inside a list or dict, `[True] == [1]` is still true.
//   * int/float stay distinct types but compare numerically and exactly, even
//     across the 2**53 boundary.
//   * `len()` of a str counts code points, not UTF-16 units.

export const isMapping = (v) => v instanceof Map;
export const isArray = (v) => Array.isArray(v);
export const isString = (v) => typeof v === 'string';
export const isBool = (v) => typeof v === 'boolean';
export const isInt = (v) => typeof v === 'bigint';
export const isFloat = (v) => typeof v === 'number';
export const isNone = (v) => v === null;

/** True for Python `int`/`float` but not `bool` — jsonschema's "number". */
export const isNumber = (v) => typeof v === 'bigint' || typeof v === 'number';

/** True for anything Python treats as a number in arithmetic, `bool` included. */
export const isNumericLike = (v) => isNumber(v) || typeof v === 'boolean';

/** float.is_integer() — false for inf and nan. */
export const floatIsIntegral = (v) => Number.isFinite(v) && Math.floor(v) === v;

/** len() of a Python str: code points. "\u{1f600}" has length 1, not 2. */
export function strLen(s) {
  let n = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const d = s.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) i++;
    }
    n++;
  }
  return n;
}

function asNumeric(v) {
  if (typeof v === 'boolean') return v ? 1n : 0n;
  return v;
}

/**
 * Python `==` for two numeric values. Mixing BigInt and Number in `==` is
 * mathematically exact per the language spec, which is precisely the CPython
 * int/float comparison rule, so 10000000000000000001 != 1e19 on both sides.
 */
export function numEq(a, b) {
  const x = asNumeric(a);
  const y = asNumeric(b);
  if (typeof x === 'bigint' && typeof y === 'bigint') return x === y;
  // eslint-disable-next-line eqeqeq
  return x == y;
}

/** Python `<`, `<=`, `>`, `>=` across int/float. NaN compares false throughout. */
export const numLt = (a, b) => asNumeric(a) < asNumeric(b);
export const numLe = (a, b) => asNumeric(a) <= asNumeric(b);
export const numGt = (a, b) => asNumeric(a) > asNumeric(b);
export const numGe = (a, b) => asNumeric(a) >= asNumeric(b);

/** Python `==`, recursively. Note that this keeps `True == 1`. */
export function pyEq(a, b) {
  if (isNumericLike(a) || isNumericLike(b)) {
    return isNumericLike(a) && isNumericLike(b) && numEq(a, b);
  }
  if (typeof a === 'string' || typeof b === 'string') return a === b;
  if (a === null || b === null) return a === null && b === null;

  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!pyEq(a[i], b[i])) return false;
    return true;
  }
  if (a instanceof Map) {
    if (!(b instanceof Map) || a.size !== b.size) return false;
    for (const [k, v] of a) {
      if (!b.has(k)) return false;
      if (!pyEq(v, b.get(k))) return false;
    }
    return true;
  }
  return false;
}

/**
 * jsonschema's `equal()`: `unbool(one) == unbool(two)`, where `unbool` swaps
 * True/False for unique sentinels so that a boolean can only ever equal the
 * same boolean. The swap is top-level only, so `[True] == [1]` stays true.
 */
export function schemaEqual(a, b) {
  if (typeof a === 'boolean' || typeof b === 'boolean') return a === b;
  return pyEq(a, b);
}

/**
 * jsonschema's `uniq()`. Both of its code paths (sort-then-compare-neighbours,
 * and the O(n^2) fallback for unorderable items) reduce to "no two elements are
 * `equal()`", which is what this checks directly.
 */
export function allUnique(items) {
  for (let i = 0; i < items.length; i++) {
    for (let j = i + 1; j < items.length; j++) {
      if (schemaEqual(items[i], items[j])) return false;
    }
  }
  return true;
}

