// Stand-ins for the CPython exceptions the original script can die from.
//
// The script prints nothing until its very last statements, so any of these
// escaping means: empty stdout, non-zero exit. Only that observable matters —
// the messages exist to make debugging the port bearable.

export class PyError extends Error {
  constructor(name, message) {
    super(message);
    this.name = name;
  }
}

export class PyTypeError extends PyError {
  constructor(message) { super('TypeError', message); }
}

export class PyAttributeError extends PyError {
  constructor(message) { super('AttributeError', message); }
}

export class PyZeroDivisionError extends PyError {
  constructor(message) { super('ZeroDivisionError', message); }
}

export class PyRecursionError extends PyError {
  constructor(message) { super('RecursionError', message); }
}

/** `re.error` — raised by re.compile on a malformed pattern. */
export class PyReError extends PyError {
  constructor(message) { super('re.error', message); }
}

