      const group = Number(esc);
      if (group > this.groupCount || group === 0) this.error(`invalid group reference ${group}`);
      return `\\${group}`;
    }

    // Any remaining ASCII letter is an error in Python ("bad escape \q").
    if (/[A-Za-z]/.test(c)) this.error(`bad escape \\${c}`);

    const cp = c.codePointAt(0);
    return inClass ? { cp } : escChar(cp);
  }

  /**
   * A character class. Emitted as a plain `[...]` when possible; when it
   * contains a complement shorthand (\W, \S, and \D in ASCII mode) it becomes
   * an alternation instead, since a JS class cannot union a complement.
   */
  parseClass() {
    let negated = false;
    if (this.peek() === '^') { this.i++; negated = true; }

    const items = []; // {cp} | {body} | {neg} | {lo, hi}
    let first = true;

    for (;;) {
      if (this.eof()) this.error('unterminated character set');
      const c = this.peek();

      // A ']' in first position is a literal, as in POSIX.
      if (c === ']' && !first) { this.i++; break; }
      first = false;

      let item;
      if (c === '\\') {
        this.i++;
        item = this.parseEscape(true);
      } else {
        this.i++;
        item = { cp: c.codePointAt(0) };
      }

      // Range?
      if (
        item.cp !== undefined && this.peek() === '-' &&
        this.peek(1) !== undefined && this.peek(1) !== ']'
      ) {
        this.i++; // '-'
        let hi;
        if (this.peek() === '\\') {
          this.i++;
          hi = this.parseEscape(true);
        } else {
          hi = { cp: this.next().codePointAt(0) };
        }
        if (hi.cp === undefined) this.error('bad character range');
        if (hi.cp < item.cp) this.error('bad character range');
        items.push({ lo: item.cp, hi: hi.cp });
        continue;
      }

      items.push(item);
    }

    if (items.length === 0) this.error('unterminated character set');

    const complements = items.filter((it) => it.neg !== undefined);
    if (complements.length === 0) {
      const body = items
        .map((it) => (it.lo !== undefined
          ? `${escChar(it.lo)}-${escChar(it.hi)}`
          : it.cp !== undefined ? escChar(it.cp) : it.body))
        .join('');
      return `[${negated ? '^' : ''}${body}]`;
    }

    // `[abc\W]` == `(?:[abc]|[^word])`, and the negated form is the same
    // alternation wrapped in a negative lookahead over one code point.
    const parts = [];
    const plainBody = items
      .filter((it) => it.neg === undefined)
      .map((it) => (it.lo !== undefined
        ? `${escChar(it.lo)}-${escChar(it.hi)}`
        : it.cp !== undefined ? escChar(it.cp) : it.body))
      .join('');
    if (plainBody) parts.push(`[${plainBody}]`);
    for (const it of complements) parts.push(`[^${it.neg}]`);
    const union = parts.join('|');
    return negated ? `(?:(?!${union})[\\s\\S])` : `(?:${union})`;
  }
}

const cache = new Map();

/**
 * `re.compile(pattern)`. Throws PyReError for anything CPython would reject.
 * The returned object exposes `search`, the only operation jsonschema uses.
 */
export function compilePattern(pattern) {
  const hit = cache.get(pattern);
  if (hit) {
    if (hit.error) throw hit.error;
    return hit.regex;
  }
  try {
    const { source, flags } = new Translator(pattern).translate();
    let regex;
    try {
      regex = new RegExp(source, flags);
    } catch (err) {
      throw new PyReError(`could not translate pattern: ${err.message}`);
    }
    const compiled = {
      source: pattern,
      jsSource: source,
      search: (s) => regex.test(s),
    };
    cache.set(pattern, { regex: compiled });
    return compiled;
  } catch (err) {
    if (err instanceof PyReError) cache.set(pattern, { error: err });
    throw err;
  }
}

/** `re.search(pattern, string)` reduced to a boolean. */
export function search(pattern, string) {
  return compilePattern(pattern).search(string);
}

