// A Python `re` -> JavaScript `RegExp` translator.
//
// Two jobs, both load-bearing:
//
//  1. Accept exactly what CPython accepts. `check_schema` runs the metaschema's
//     `format: "regex"` check, which is literally `re.compile(...)`, so a
//     pattern Python rejects must raise here too (the script then dies before
//     printing anything). `\p{L}` and `(?<n>x)` are valid JS but invalid Python;
//     `(?P<n>x)`, `[]]`, `a{`, `a*+` and `(?>a)` are the reverse.
//
//  2. Match exactly what CPython matches. The two engines disagree on more than
//     you would like:
//       $   Python also matches just before a single trailing newline
//       .   Python excludes only \n; JS also excludes \r,  ,
//       \d  Python is all of Unicode Nd; JS is [0-9]
//       \w  Python is Unicode alphanumerics; JS is [A-Za-z0-9_]
//       \s  Python includes \x1c-\x1f and \x85 but not
//       \b  Python's word set is Unicode; JS's is ASCII
//       ^$  under (?m) Python breaks only on \n; JS also breaks on \r
//
// Everything is rewritten into explicit constructs under the `u` flag, so the
// `m` and `s` flags are never handed to JS — their semantics are emitted inline.

import { PyReError } from '../py/errors.mjs';

const DIGITS = '0123456789';
const OCTDIGITS = '01234567';
const HEXDIGITS = '0123456789abcdefABCDEF';
const VERBOSE_WS = ' \t\n\r\f\v';

// Class bodies, usable both inside [...] and (wrapped) outside.
const WORD_U = '\\p{L}\\p{N}_';
const WORD_A = 'A-Za-z0-9_';
const DIGIT_U = '\\p{Nd}';
const DIGIT_A = '0-9';
// Py_UNICODE_ISSPACE: 09-0D, 1C-1F, 20, 85, A0, 1680, 2000-200A, 2028, 2029,
// 202F, 205F, 3000. Notably no U+FEFF, which JS's \s does include.
const SPACE_U =
  '\\t-\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000';
const SPACE_A = '\\t-\\r ';

const SIMPLE_ESCAPES = {
  a: 0x07,
  f: 0x0c,
  n: 0x0a,
  r: 0x0d,
  t: 0x09,
  v: 0x0b,
};

/** Render one code point so that it is a literal in JS `u` mode, anywhere. */
function escChar(cp) {
  if ((cp >= 0x30 && cp <= 0x39) || (cp >= 0x41 && cp <= 0x5a) || (cp >= 0x61 && cp <= 0x7a)) {
    return String.fromCodePoint(cp);
  }
  return `\\u{${cp.toString(16)}}`;
}

class Translator {
  constructor(pattern) {
    this.src = Array.from(pattern); // code points, so astral chars are one unit
    this.i = 0;
    this.flags = { i: false, m: false, s: false, x: false, a: false };
    this.groupCount = 0; // groups opened so far, mirroring sre's running count
    this.groupNames = new Set();
    this.atomicSeq = 0;
    this.atStart = true;
  }

  error(msg) {
    throw new PyReError(`${msg} at position ${this.i}`);
  }

  peek(k = 0) { return this.src[this.i + k]; }
  next() { return this.src[this.i++]; }
  eof() { return this.i >= this.src.length; }

  // ---- character-set helpers, flag aware -------------------------------

  wordBody() { return this.flags.a ? WORD_A : WORD_U; }
  digitBody() { return this.flags.a ? DIGIT_A : DIGIT_U; }
  spaceBody() { return this.flags.a ? SPACE_A : SPACE_U; }

  // ---- entry point -----------------------------------------------------

  translate() {
    this.readGlobalFlags();
    const body = this.parseAlternation(0);
    if (!this.eof()) {
      // Only an unmatched ')' can stop us at depth 0.
      this.error('unbalanced parenthesis');
    }
    let jsFlags = 'u';
    if (this.flags.i) jsFlags += 'i';
    return { source: body, flags: jsFlags };
  }

  /** Leading `(?aimsux)` groups set flags for the whole pattern. */
  readGlobalFlags() {
    for (;;) {
      if (this.peek() !== '(' || this.peek(1) !== '?') return;
      let j = this.i + 2;
      let letters = '';
      while (j < this.src.length && /[aiLmsux]/.test(this.src[j])) letters += this.src[j++];
      if (letters === '' || this.src[j] !== ')') return;
      this.applyFlags(letters);
      this.i = j + 1;
    }
  }

  applyFlags(letters) {
    for (const ch of letters) {
      if (ch === 'L') this.error('bad inline flags: cannot use \'L\' flag with a str pattern');
      if (ch === 'u' && this.flags.a) {
        this.error('bad inline flags: cannot use both \'a\' and \'u\' flags');
      }
      if (ch === 'a') {
        if (letters.includes('u')) {
          this.error('bad inline flags: cannot use both \'a\' and \'u\' flags');
        }
        this.flags.a = true;
      } else if (ch !== 'u') {
        this.flags[ch] = true;
      }
    }
  }

  // ---- grammar ---------------------------------------------------------

  parseAlternation(depth) {
    const branches = [this.parseSequence(depth)];
    while (this.peek() === '|') {
      this.i++;
      branches.push(this.parseSequence(depth));
    }
    return branches.join('|');
  }

  parseSequence(depth) {
    const pieces = [];
    for (;;) {
      if (this.eof()) break;
      const c = this.peek();
      if (c === '|') break;
      if (c === ')') {
        if (depth > 0) break;
        this.error('unbalanced parenthesis');
      }
      if (this.flags.x) {
        if (VERBOSE_WS.includes(c)) { this.i++; continue; }
        if (c === '#') {
          while (!this.eof() && this.peek() !== '\n') this.i++;
          continue;
        }
      }
      const atom = this.parseAtom(depth);
      if (atom === null) continue; // e.g. a (?#...) comment
      pieces.push(this.parseQuantifier(atom));
    }
    return pieces.join('');
  }

  /**
   * Quantifiers, including the two Python-only forms:
   *   X*+  possessive  -> (?=(X*))\k<n>
   *   {,n}             -> {0,n}
   * A `{` that does not open a well-formed quantifier is a literal in Python.
   */
  parseQuantifier(atom) {
    const c = this.peek();
    let quant = null;

    if (c === '*' || c === '+' || c === '?') {
      this.i++;
      quant = c;
    } else if (c === '{') {
      const save = this.i;
      const parsed = this.tryParseBraceQuantifier();
      if (parsed === null) { this.i = save; return atom; }
      quant = parsed;
    } else {
      return atom;
    }

    if (atom === '') this.error('nothing to repeat');

    // lazy / possessive modifier
    let possessive = false;
    if (this.peek() === '?') { this.i++; quant += '?'; }
    else if (this.peek() === '+') { this.i++; possessive = true; }

    if ('*+?{'.includes(this.peek() ?? '')) {
      // `a**` — Python rejects a quantifier applied to a quantifier.
      if (this.peek() !== '{' || this.lookaheadIsBraceQuantifier()) {
        this.error('multiple repeat');
      }
    }

    if (possessive) {
      const name = `_$a${this.atomicSeq++}`;
      return `(?=(?<${name}>${atom}${quant}))\\k<${name}>`;
    }
    return atom + quant;
  }

  lookaheadIsBraceQuantifier() {
    const save = this.i;
    const r = this.tryParseBraceQuantifier();
    this.i = save;
    return r !== null;
  }

  tryParseBraceQuantifier() {
    if (this.peek() !== '{') return null;
    let j = this.i + 1;
    let lo = '';
    let hi = '';
    let comma = false;
    while (j < this.src.length && DIGITS.includes(this.src[j])) lo += this.src[j++];
    if (this.src[j] === ',') { comma = true; j++; while (j < this.src.length && DIGITS.includes(this.src[j])) hi += this.src[j++]; }
    if (this.src[j] !== '}') return null;
    if (lo === '' && hi === '' ) return null; // `{}` and `{,}` are literals
    this.i = j + 1;
    if (!comma) return `{${lo}}`;
    if (lo === '') return `{0,${hi}}`;
    if (hi === '') return `{${lo},}`;
    if (Number(lo) > Number(hi)) this.error('min repeat greater than max repeat');
    return `{${lo},${hi}}`;
  }

  parseAtom(depth) {
    const c = this.next();

    if (c === '(') return this.parseGroup(depth);
    if (c === '[') return this.parseClass();
    if (c === '\\') return this.parseEscape(false);

    if (c === '.') return this.flags.s ? '[\\s\\S]' : '[^\\n]';
    // Python's ^/$ never see \r as a line break, and bare $ also matches
    // immediately before one trailing newline.
    if (c === '^') return this.flags.m ? '(?:^|(?<=\\n))' : '^';
    if (c === '$') return this.flags.m ? '(?=\\n|$)' : '(?=\\n?$)';

    if (c === '*' || c === '+' || c === '?') this.error('nothing to repeat');
    if (c === '{') {
      // A brace that starts a real quantifier here has nothing to repeat.
      this.i--;
      if (this.lookaheadIsBraceQuantifier()) this.error('nothing to repeat');
      this.i++;
      return escChar(0x7b);
    }
    return escChar(c.codePointAt(0));
  }

  parseGroup(depth) {
    if (this.peek() !== '?') {
      this.groupCount++;
      const inner = this.parseAlternation(depth + 1);
      this.expect(')');
      return `(${inner})`;
    }
    this.i++; // '?'
    const c = this.peek();

    if (c === ':') {
      this.i++;
      const inner = this.parseAlternation(depth + 1);
      this.expect(')');
      return `(?:${inner})`;
    }

    if (c === '#') {
      this.i++;
      while (!this.eof() && this.peek() !== ')') this.i++;
      if (this.eof()) this.error('missing ), unterminated comment');
      this.i++;
      return null;
    }

    if (c === '=' || c === '!') {
      this.i++;
      const inner = this.parseAlternation(depth + 1);
      this.expect(')');
      return `(?${c}${inner})`;
    }

    if (c === '<' && (this.peek(1) === '=' || this.peek(1) === '!')) {
      const kind = this.peek(1);
      this.i += 2;
      const start = this.i;
      const inner = this.parseAlternation(depth + 1);
      const raw = this.src.slice(start, this.i).join('');
      this.expect(')');
      // Python requires a fixed-width lookbehind; JS does not, so reject here.
      if (/(?<!\\)[*+]/.test(raw) || /(?<!\\)\{\d*,\d*\}/.test(raw)) {
        this.error('look-behind requires fixed-width pattern');
      }
      return `(?<${kind}${inner})`;
    }

    if (c === '>') {
      this.i++;
      const inner = this.parseAlternation(depth + 1);
      this.expect(')');
      const name = `_$a${this.atomicSeq++}`;
      return `(?=(?<${name}>${inner}))\\k<${name}>`;
    }

    if (c === '(') {
      // Conditional (?(id)yes|no) — no JS equivalent. Validate the group
      // reference the way Python does, then refuse.
      this.i++;
      let ref = '';
      while (!this.eof() && this.peek() !== ')') ref += this.next();
      this.expect(')');
      if (/^\d+$/.test(ref)) {
        if (Number(ref) === 0) this.error('bad group number');
        if (Number(ref) > this.groupCount) this.error(`invalid group reference ${ref}`);
      } else if (!this.groupNames.has(ref)) {
        this.error(`unknown group name '${ref}'`);
      }
      throw new PyReError('conditional expressions are not supported by this port');
    }

    if (c === 'P') {
      this.i++;
      const k = this.peek();
      if (k === '<') {
        this.i++;
        let name = '';
        while (!this.eof() && this.peek() !== '>') name += this.next();
        if (this.eof()) this.error('missing >, unterminated name');
        this.i++;
        if (!/^[\p{L}_][\p{L}\p{N}_]*$/u.test(name)) {
          this.error(`bad character in group name '${name}'`);
        }
        if (this.groupNames.has(name)) this.error(`redefinition of group name '${name}'`);
        this.groupNames.add(name);
        this.groupCount++;
        const inner = this.parseAlternation(depth + 1);
        this.expect(')');
        return `(?<${name}>${inner})`;
      }
      if (k === '=') {
        this.i++;
        let name = '';
        while (!this.eof() && this.peek() !== ')') name += this.next();
        this.expect(')');
        if (!this.groupNames.has(name)) this.error(`unknown group name '${name}'`);
        return `\\k<${name}>`;
      }
      this.error('unknown extension ?P');
    }

    if (c === '<') this.error('unknown extension ?<');

    // (?flags) handled at the start only; (?flags:...) is scoped in Python but
    // is applied globally here — JS has no per-group modifiers before ES2025.
    if (/[aiLmsux-]/.test(c ?? '')) {
      let letters = '';
      while (!this.eof() && /[aiLmsux]/.test(this.peek())) letters += this.next();
      let off = '';
      if (this.peek() === '-') {
        this.i++;
        while (!this.eof() && /[aimsux]/.test(this.peek())) off += this.next();
      }
      if (this.peek() === ')') {
        this.i++;
        this.error('global flags not at the start of the expression');
      }
      if (this.peek() !== ':') this.error('missing -, : or )');
      this.i++;
      if (letters) this.applyFlags(letters);
      const inner = this.parseAlternation(depth + 1);
      this.expect(')');
      return `(?:${inner})`;
    }

    this.error('unknown extension');
  }

  expect(ch) {
    if (this.peek() !== ch) {
      this.error(ch === ')' ? 'missing ), unterminated subpattern' : `expected ${ch}`);
    }
    this.i++;
  }

  /**
   * An escape sequence. `inClass` switches to the character-class dialect,
   * where anchors and back-references are not available and the shorthand
   * classes must be emitted as bare class bodies.
   */
  parseEscape(inClass) {
    if (this.eof()) this.error('bad escape (end of pattern)');
    const c = this.next();

    // Shorthand classes.
    if (c === 'd') return inClass ? { body: this.digitBody() } : `[${this.digitBody()}]`;
    if (c === 'D') {
      if (inClass) return this.flags.a ? { body: null, neg: DIGIT_A } : { body: '\\P{Nd}' };
      return `[^${this.digitBody()}]`;
    }
    if (c === 'w') return inClass ? { body: this.wordBody() } : `[${this.wordBody()}]`;
    if (c === 'W') return inClass ? { neg: this.wordBody() } : `[^${this.wordBody()}]`;
    if (c === 's') return inClass ? { body: this.spaceBody() } : `[${this.spaceBody()}]`;
    if (c === 'S') return inClass ? { neg: this.spaceBody() } : `[^${this.spaceBody()}]`;

    if (!inClass) {
      const w = this.wordBody();
      if (c === 'b') return `(?:(?<![${w}])(?=[${w}])|(?<=[${w}])(?![${w}]))`;
      if (c === 'B') return `(?:(?<=[${w}])(?=[${w}])|(?<![${w}])(?![${w}]))`;
      if (c === 'A') return '^';
      if (c === 'Z') return '$';
    } else if ('bB'.includes(c)) {
      // \b inside a class is the backspace character in Python.
      if (c === 'b') return { cp: 0x08 };
      this.error('bad escape \\B');
    } else if ('AZ'.includes(c)) {
      this.error(`bad escape \\${c}`);
    }

    if (Object.prototype.hasOwnProperty.call(SIMPLE_ESCAPES, c)) {
      const cp = SIMPLE_ESCAPES[c];
      return inClass ? { cp } : escChar(cp);
    }

    if (c === 'x') {
      let hex = '';
      while (hex.length < 2 && HEXDIGITS.includes(this.peek() ?? '')) hex += this.next();
      if (hex.length !== 2) this.error('incomplete escape \\x');
      const cp = parseInt(hex, 16);
      return inClass ? { cp } : escChar(cp);
    }

    if (c === 'u' || c === 'U') {
      const want = c === 'u' ? 4 : 8;
      let hex = '';
      while (hex.length < want && HEXDIGITS.includes(this.peek() ?? '')) hex += this.next();
      if (hex.length !== want) this.error(`incomplete escape \\${c}`);
      const cp = parseInt(hex, 16);
      if (cp > 0x10ffff) this.error(`bad escape \\${c}`);
      return inClass ? { cp } : escChar(cp);
    }

    if (c === 'N') {
      // \N{NAME} needs the Unicode name database; out of scope for this port.
      throw new PyReError('\\N{...} escapes are not supported by this port');
    }

    if (c === '0') {
      let oct = '0';
      while (oct.length < 3 && OCTDIGITS.includes(this.peek() ?? '')) oct += this.next();
      const cp = parseInt(oct, 8) & 0xff;
      return inClass ? { cp } : escChar(cp);
    }

    if (DIGITS.includes(c)) {
      let esc = c;
      if (DIGITS.includes(this.peek() ?? '')) {
        esc += this.next();
        if (
          OCTDIGITS.includes(esc[0]) && OCTDIGITS.includes(esc[1]) &&
          OCTDIGITS.includes(this.peek() ?? '')
        ) {
          esc += this.next();
          const cp = parseInt(esc, 8) & 0xff;
