// jsonschema's exception and error-tree types.
//
// Only two observables of ValidationError matter to this port: `path` (the
// absolute instance path) and `validator` (the keyword that produced it).
// Everything printed by the script is derived from those two.

export class ValidationError {
  constructor(message, { validator, path = [], instance, schema, context = [] } = {}) {
    this.message = message;
    // `undefined` means "not set yet" — iter_errors fills it in with the
    // keyword name on the way out, but only if it is still unset, which is why
    // an error raised by a subschema keeps the inner keyword. `null` is the
    // explicit Python `None` used for false-schema errors.
    this.validator = validator;
    this.path = path;
    this.instance = instance;
    this.schema = schema;
    this.context = context;
  }
}

export class SchemaError extends Error {
  constructor(error) {
    super(error.message);
    this.name = 'SchemaError';
    this.error = error;
  }
}

export class UnknownType extends Error {
  constructor(type) {
    super(`Unknown type ${JSON.stringify(type)}`);
    this.name = 'UnknownType';
  }
}

export class FormatError extends Error {
  constructor(message, cause) {
    super(message);
    this.name = 'FormatError';
    this.cause = cause;
  }
}

/** referencing.exceptions.Unresolvable, surfaced as _WrappedReferencingError. */
export class Unresolvable extends Error {
  constructor(ref) {
    super(`Unresolvable: ${ref}`);
    this.name = 'Unresolvable';
  }
}

export class PointerToNowhere extends Error {
  constructor(pointer) {
    super(`PointerToNowhere: ${JSON.stringify(pointer)} does not exist`);
    this.name = 'PointerToNowhere';
  }
}

export class NoSuchAnchor extends Error {
  constructor(anchor) {
    super(`NoSuchAnchor: ${JSON.stringify(anchor)}`);
    this.name = 'NoSuchAnchor';
  }
}

/**
 * ErrorTree.
 *
 * Each error is filed at the node named by its absolute instance path, into a
 * dict keyed by the *validator keyword*. That dict is the whole story behind
 * the script's first printed line: three `required` errors at the root all key
 * on "required", so two of them are overwritten and `total_errors` is 1 while
 * `len(errors)` is 3.
 */
export class ErrorTree {
  constructor(errors = []) {
    this.errors = new Map(); // keyword (or null) -> error
    this.children = new Map(); // path element -> ErrorTree

    for (const error of errors) {
      let container = this;
      for (const element of error.path) container = container.childFor(element);
      const key = error.validator === undefined ? null : error.validator;
      container.errors.set(key, error);
    }
  }

  /**
   * Python dict keys keep `0` and `"0"` apart, so array indices and property
   * names must not collide here either.
   */
  childFor(element) {
    const key = typeof element === 'string' ? `s${element}` : `i${element}`;
    let child = this.children.get(key);
    if (child === undefined) {
      child = new ErrorTree();
      this.children.set(key, child);
    }
    return child;
  }

  get totalErrors() {
    let total = this.errors.size;
    for (const child of this.children.values()) total += child.totalErrors;
    return total;
  }
}

