// The Draft 6/7 type checker.
//
// Two rules a JavaScript-shaped implementation tends to miss:
//   * `bool` is excluded from "number" and "integer" even though Python's bool
//     is an int subclass;
//   * from Draft 6 onwards a float with no fractional part *is* an "integer",
//     so 1.0 satisfies {"type": "integer"}.

import { UnknownType } from './exceptions.mjs';
import { floatIsIntegral, isFloat, isInt, isNumber } from '../py/values.mjs';

export function isTypeOf(instance, type) {
  switch (type) {
    case 'array': return Array.isArray(instance);
    case 'boolean': return typeof instance === 'boolean';
    case 'integer': return isInt(instance) || (isFloat(instance) && floatIsIntegral(instance));
    case 'null': return instance === null;
    case 'number': return isNumber(instance);
    case 'object': return instance instanceof Map;
    case 'string': return typeof instance === 'string';
    default: throw new UnknownType(type);
  }
}

