// The format checker used by `check_schema`.
//
// `Draft7Validator(schema)` is built without a format checker, so `format` is
// inert during normal validation. `check_schema`, however, defaults to the
// draft's FORMAT_CHECKER, which is why an unparseable "pattern" kills the
// script before it prints anything.
//
// Of the three formats the Draft-07 metaschema uses — uri, uri-reference and
// regex — only "regex" is actually enabled in the bundled interpreter: the uri
// checkers need the optional `rfc3987` package, and probing confirms
// {"$schema": "not a uri"} and {"$id": "not a uri"} both validate cleanly.

import { FormatError } from './exceptions.mjs';
import { compilePattern } from '../py/pyregex.mjs';

export const DRAFT7_FORMAT_CHECKER = {
  check(instance, format) {
    if (format !== 'regex') return; // unregistered formats are skipped entirely
    if (typeof instance !== 'string') return; // is_regex passes non-strings
    try {
      compilePattern(instance);
    } catch (err) {
      throw new FormatError(`${JSON.stringify(instance)} is not a 'regex'`, err);
    }
  },
};

