  DRAFT4_METASCHEMA_TEXT,
  DRAFT4_METASCHEMA_URI,
  DRAFT6_METASCHEMA_TEXT,
  DRAFT6_METASCHEMA_URI,
  DRAFT7_METASCHEMA_TEXT,
  DRAFT7_METASCHEMA_URI,
} from './metaschemas.mjs';

// ---------------------------------------------------------------------------
// RFC 3986 reference resolution. Written by hand because the base URI is very
// often the empty string, which WHATWG `URL` refuses to work with.
// ---------------------------------------------------------------------------

const URI_RE = /^(?:([A-Za-z][A-Za-z0-9+\-.]*):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/;

