  const m = URI_RE.exec(uri);
  return {
    scheme: m[1],
    authority: m[2],
    path: m[3] ?? '',
    query: m[4],
    fragment: m[5],
  };
}

function removeDotSegments(path) {
  const out = [];
  let input = path;
  while (input.length > 0) {
    if (input.startsWith('../')) input = input.slice(3);
    else if (input.startsWith('./')) input = input.slice(2);
    else if (input === '/.' || input.startsWith('/./')) input = `/${input.slice(3)}`;
    else if (input === '/..' || input.startsWith('/../')) {
      input = `/${input.slice(4)}`;
      out.pop();
    } else if (input === '.' || input === '..') input = '';
    else {
      const nextSlash = input.indexOf('/', 1);
      const seg = nextSlash === -1 ? input : input.slice(0, nextSlash);
      out.push(seg);
      input = nextSlash === -1 ? '' : input.slice(nextSlash);
    }
  }
  return out.join('');
