// Python operator semantics that the keyword implementations lean on.
//
// These exist so that a schema like {"minimum": "5"} fails the same way it does
// in Python — with a TypeError from `<`, killing the script — instead of
// silently coercing the way JavaScript would.

import { PyAttributeError, PyTypeError } from './errors.mjs';
import { isNumericLike, numGe, numGt, numLe, numLt, pyEq } from './values.mjs';

/** Python truthiness. Note that NaN is truthy and 0.0 is not. */
export function pyTruthy(v) {
  if (v === null || v === false) return false;
  if (v === true) return true;
  if (typeof v === 'bigint') return v !== 0n;
  if (typeof v === 'number') return v !== 0; // NaN is truthy, as in Python
  if (typeof v === 'string') return v.length > 0;
  if (Array.isArray(v)) return v.length > 0;
  if (v instanceof Map) return v.size > 0;
  return true;
}

/** `len(v)` — only defined for the sized types JSON can produce. */
export function pyLen(v) {
  if (typeof v === 'string') {
    let n = 0;
    for (const _ of v) n++;
    return n;
  }
  if (Array.isArray(v)) return v.length;
  if (v instanceof Map) return v.size;
  throw new PyTypeError(`object of type '${typeName(v)}' has no len()`);
}

/** `for x in v` — dicts iterate their keys. */
export function pyIter(v) {
  if (Array.isArray(v)) return v;
  if (v instanceof Map) return [...v.keys()];
  if (typeof v === 'string') return [...v];
  throw new PyTypeError(`'${typeName(v)}' object is not iterable`);
}

/** `v.items()` */
export function pyItems(v) {
  if (v instanceof Map) return [...v.entries()];
  throw new PyAttributeError(`'${typeName(v)}' object has no attribute 'items'`);
}

/** `item in container` */
export function pyContains(container, item) {
  if (container instanceof Map) return typeof item === 'string' && container.has(item);
  if (Array.isArray(container)) return container.some((each) => pyEq(each, item));
  if (typeof container === 'string') {
    if (typeof item !== 'string') {
      throw new PyTypeError("'in <string>' requires string as left operand");
    }
    return container.includes(item);
  }
  throw new PyTypeError(`argument of type '${typeName(container)}' is not iterable`);
}

