// The Draft-07 keyword implementations.
//
// Each generator mirrors its counterpart in jsonschema's _keywords.py /
// _legacy_keywords.py, because the script prints error *counts* and the tree
// groups by (instance path, keyword) — so how many errors a keyword yields, the
// path it hangs them on, and the keyword label each one carries are all
// observable. A few that are easy to get wrong:
//
//   required              one error per missing property, all at the parent
//                         path, all labelled "required" — so three missing
//                         properties are three errors but one tree entry
//   additionalProperties  a single error listing every extra when false,
//                         but one error *per* extra when it is a schema
//   dependencies (array)  one error per missing dependency, parent path
//   propertyNames         errors land on the parent, labelled with the inner
//                         keyword, because descend() is called with no path
//   anyOf / oneOf         at most one error each, whatever the branch count

import { ValidationError } from './exceptions.mjs';
import {
  pyContains, pyGe, pyGt, pyItems, pyIter, pyLe, pyLen, pyLt, pyTruthy,
} from '../py/ops.mjs';
import { allUnique, isFloat, isInt, pyEq, schemaEqual, strLen } from '../py/values.mjs';
import { PyTypeError, PyValueError, PyZeroDivisionError } from '../py/errors.mjs';
import { search } from '../py/pyregex.mjs';

const err = (message) => new ValidationError(message);

function* ref(validator, reference, instance) {
  yield* validator.validateReference(reference, instance);
}

function* additionalItems(validator, aI, instance, schema) {
  const items = schema.has('items') ? schema.get('items') : new Map();
  if (!validator.isType(instance, 'array') || validator.isType(items, 'object')) return;

  const lenItems = pyLen(schema.has('items') ? schema.get('items') : []);
  if (validator.isType(aI, 'object')) {
    for (let index = lenItems; index < instance.length; index++) {
      yield* validator.descend(instance[index], aI, index);
    }
  } else if (!pyTruthy(aI) && instance.length > lenItems) {
    yield err('Additional items are not allowed');
  }
}

/** The extras are found with ONE combined regex, joined by "|". */
function findAdditionalProperties(instance, schema) {
  const properties = schema.has('properties') ? schema.get('properties') : new Map();
  const patternProps = schema.has('patternProperties') ? schema.get('patternProperties') : new Map();
  const patterns = pyIter(patternProps).join('|');
  const out = [];
  for (const property of instance.keys()) {
    if (!pyContains(properties, property)) {
      if (patterns !== '' && search(patterns, property)) continue;
      out.push(property);
    }
  }
  return out;
}

function* additionalProperties(validator, aP, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  const extras = findAdditionalProperties(instance, schema);

  if (validator.isType(aP, 'object')) {
    for (const extra of extras) {
      yield* validator.descend(instance.get(extra), aP, extra);
    }
  } else if (!pyTruthy(aP) && extras.length > 0) {
    yield err('Additional properties are not allowed');
  }
}

function* allOf(validator, subschemas, instance) {
  for (const subschema of pyIter(subschemas)) {
    yield* validator.descend(instance, subschema);
  }
}

function* anyOf(validator, subschemas, instance) {
  const allErrors = [];
  for (const subschema of pyIter(subschemas)) {
    const errors = [...validator.descend(instance, subschema)];
    if (errors.length === 0) return; // a branch passed
    allErrors.push(...errors);
  }
  yield new ValidationError('is not valid under any of the given schemas', {
    context: allErrors,
  });
}

function* oneOf(validator, subschemas, instance) {
  const branches = pyIter(subschemas);
  const allErrors = [];
  let firstValidIndex = -1;

  for (let index = 0; index < branches.length; index++) {
    const errors = [...validator.descend(instance, branches[index])];
    if (errors.length === 0) { firstValidIndex = index; break; }
    allErrors.push(...errors);
  }

  if (firstValidIndex === -1) {
    yield new ValidationError('is not valid under any of the given schemas', {
      context: allErrors,
    });
    return;
  }

  // Python keeps consuming the *same* iterator, so only the branches after the
  // first match are re-checked.
  for (let index = firstValidIndex + 1; index < branches.length; index++) {
    if (validator.evolve(branches[index]).isValid(instance)) {
      yield err('is valid under each of the given schemas');
      return;
    }
  }
}

function* not_(validator, notSchema, instance) {
  if (validator.evolve(notSchema).isValid(instance)) {
    yield err('should not be valid under the given schema');
  }
}

function* if_(validator, ifSchema, instance, schema) {
  if (validator.evolve(ifSchema).isValid(instance)) {
    if (schema.has('then')) yield* validator.descend(instance, schema.get('then'));
  } else if (schema.has('else')) {
    yield* validator.descend(instance, schema.get('else'));
  }
}

function* constKeyword(validator, constValue, instance) {
  if (!schemaEqual(instance, constValue)) yield err('was expected');
}

function* enumKeyword(validator, enums, instance) {
  // Python: `if instance == 0 or instance == 1`, which is how True/False slip
  // in — they need the unbool-aware comparison instead of plain `in`.
  if (pyEq(instance, 0n) || pyEq(instance, 1n)) {
    for (const each of pyIter(enums)) if (schemaEqual(instance, each)) return;
    yield err('is not one of the enum values');
    return;
  }
  if (!pyContains(enums, instance)) yield err('is not one of the enum values');
}

function* contains(validator, containsSchema, instance) {
  if (!validator.isType(instance, 'array')) return;
  for (const element of instance) {
    if (validator.evolve(containsSchema).isValid(element)) return;
  }
  yield err('None of the items are valid under the given schema');
}

function* dependencies(validator, deps, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, dependency] of pyItems(deps)) {
    if (!pyContains(instance, property)) continue;
    if (validator.isType(dependency, 'array')) {
      for (const each of dependency) {
        if (!pyContains(instance, each)) yield err(`${each} is a dependency of ${property}`);
      }
    } else {
      yield* validator.descend(instance, dependency);
    }
  }
}

function* items(validator, itemsSchema, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (validator.isType(itemsSchema, 'array')) {
    const n = Math.min(instance.length, itemsSchema.length);
    for (let index = 0; index < n; index++) {
      yield* validator.descend(instance[index], itemsSchema[index], index);
    }
  } else {
    for (let index = 0; index < instance.length; index++) {
      yield* validator.descend(instance[index], itemsSchema, index);
    }
  }
}

function* properties(validator, props, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, subschema] of pyItems(props)) {
    if (instance.has(property)) {
      yield* validator.descend(instance.get(property), subschema, property);
    }
  }
}

function* patternProperties(validator, patternProps, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [pattern, subschema] of pyItems(patternProps)) {
    for (const [k, v] of instance) {
      if (search(pattern, k)) yield* validator.descend(v, subschema, k);
    }
  }
}

/** No path is passed to descend, so these errors surface on the parent node. */
function* propertyNames(validator, nameSchema, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of instance.keys()) {
    yield* validator.descend(property, nameSchema);
  }
}

function* required(validator, requiredProps, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of pyIter(requiredProps)) {
    if (!pyContains(instance, property)) yield err(`${property} is a required property`);
  }
}

function* minProperties(validator, mP, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (pyLt(BigInt(instance.size), mP)) yield err('does not have enough properties');
}

function* maxProperties(validator, mP, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (pyGt(BigInt(instance.size), mP)) yield err('has too many properties');
}

function* minItems(validator, mI, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (pyLt(BigInt(instance.length), mI)) yield err('is too short');
}

function* maxItems(validator, mI, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (pyGt(BigInt(instance.length), mI)) yield err('is too long');
}

function* minLength(validator, mL, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (pyLt(BigInt(strLen(instance)), mL)) yield err('is too short');
}

function* maxLength(validator, mL, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (pyGt(BigInt(strLen(instance)), mL)) yield err('is too long');
}

function* pattern(validator, patrn, instance) {
  if (validator.isType(instance, 'string') && !search(patrn, instance)) {
    yield err('does not match the pattern');
  }
}

function* minimum(validator, minimumValue, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (pyLt(instance, minimumValue)) yield err('is less than the minimum');
}

function* maximum(validator, maximumValue, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (pyGt(instance, maximumValue)) yield err('is greater than the maximum');
}

function* exclusiveMinimum(validator, minimumValue, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (pyLe(instance, minimumValue)) yield err('is less than or equal to the minimum');
}

function* exclusiveMaximum(validator, maximumValue, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (pyGe(instance, maximumValue)) yield err('is greater than or equal to the maximum');
}

/**
 * The int/float distinction is load-bearing: a float divisor goes through
 * `int(instance / dB) != instance / dB`, an int divisor through `instance % dB`.
 * 0.0075 is a multiple of 0.0001 by the second rule and not by the first.
 */
function* multipleOf(validator, dB, instance) {
  if (!validator.isType(instance, 'number')) return;

  let failed;
  if (isFloat(dB)) {
    if (dB === 0) throw new PyZeroDivisionError('float division by zero');
    const quotient = Number(instance) / dB;
    if (Number.isNaN(quotient)) {
      throw new PyValueError('cannot convert float NaN to integer');
    }
    if (!Number.isFinite(quotient)) failed = true; // int() raises OverflowError
    else failed = Math.trunc(quotient) !== quotient;
  } else if (isInt(dB)) {
    if (dB === 0n) throw new PyZeroDivisionError('integer division or modulo by zero');
    if (isInt(instance)) failed = instance % dB !== 0n;
    else failed = pyTruthy(instance % Number(dB));
  } else {
    throw new PyTypeError("unsupported operand type(s) for %: 'number' and other");
  }

  if (failed) yield err('is not a multiple of the given value');
}

function* uniqueItems(validator, uI, instance) {
  if (pyTruthy(uI) && validator.isType(instance, 'array') && !allUnique(instance)) {
    yield err('has non-unique elements');
  }
}

function* typeKeyword(validator, types, instance) {
  const list = typeof types === 'string' ? [types] : pyIter(types);
  for (const type of list) if (validator.isType(instance, type)) return;
  yield err('is not of the expected type');
}

/** Inert unless a format checker is attached — which only check_schema does. */
function* format(validator, formatName, instance) {
  if (validator.formatChecker === null) return;
  try {
    validator.formatChecker.check(instance, formatName);
  } catch (error) {
    if (error?.name !== 'FormatError') throw error;
    yield err(error.message);
  }
}

export const DRAFT7_VALIDATORS = new Map(Object.entries({
  $ref: ref,
  additionalItems,
  additionalProperties,
  allOf,
  anyOf,
  const: constKeyword,
  contains,
  dependencies,
  enum: enumKeyword,
  exclusiveMaximum,
  exclusiveMinimum,
  format,
  if: if_,
  items,
  maxItems,
  maxLength,
  maxProperties,
  maximum,
  minItems,
  minLength,
  minProperties,
  minimum,
  multipleOf,
  not: not_,
  oneOf,
  patternProperties,
  pattern,
  properties,
  propertyNames,
  required,
  type: typeKeyword,
  uniqueItems,
}));

