// Draft7Validator.
//
// The three details that shape everything else:
//   * a `$ref` suppresses every sibling keyword (Draft-07 semantics), which is
//     why {"$ref": ..., "minimum": 100} reports only the ref's errors;
//   * `iter_errors` labels an error with the current keyword only if it is not
//     labelled already, so an error raised deep inside `propertyNames` or
//     `allOf` keeps the inner keyword — that is what drives ErrorTree grouping;
//   * `check_schema` runs the meta-schema *with* a format checker, and raises
//     on the first error.

import { DRAFT7_VALIDATORS } from './keywords.mjs';
import { SchemaError, ValidationError } from './exceptions.mjs';
import { isTypeOf } from './typechecker.mjs';
import { draft7Metaschema, resolverForRoot } from './referencing.mjs';
import { DRAFT7_FORMAT_CHECKER } from './formats.mjs';
import { PyAttributeError } from '../py/errors.mjs';
import { typeName } from '../py/ops.mjs';

/** Draft-07's `ignore_ref_siblings`: `$ref` wins outright when present. */
function applicableValidators(schema) {
  const ref = schema.get('$ref');
  if (ref !== undefined && ref !== null) return [['$ref', ref]];
  return [...schema.entries()];
}

export class Draft7Validator {
  constructor(schema, { formatChecker = null, resolver = null } = {}) {
    this.schema = schema;
    this.formatChecker = formatChecker;
    this.resolver = resolver ?? resolverForRoot(schema);
  }

  evolve(schema, resolver) {
    return new Draft7Validator(schema, {
      formatChecker: this.formatChecker,
      resolver: resolver ?? this.resolver,
    });
  }

  isType(instance, type) {
    return isTypeOf(instance, type);
  }

  *iterErrors(instance) {
    const { schema } = this;

    if (schema === true) return; // `True` is validated as `{}`
    if (schema === false) {
      // Note the explicit `None` validator — it is a distinct ErrorTree key.
      yield new ValidationError('False schema does not allow the instance', {
        validator: null,
        instance,
        schema,
      });
      return;
    }
    if (!(schema instanceof Map)) {
      // Python reaches for `.get` on the schema and blows up on anything else.
      throw new PyAttributeError(`'${typeName(schema)}' object has no attribute 'get'`);
    }

    for (const [k, v] of applicableValidators(schema)) {
      const keywordFn = DRAFT7_VALIDATORS.get(k);
      if (keywordFn === undefined) continue; // unknown keywords are ignored
      for (const error of keywordFn(this, v, instance, schema)) {
        if (error.validator === undefined) error.validator = k;
        if (error.instance === undefined) error.instance = instance;
        if (error.schema === undefined) error.schema = schema;
        yield error;
      }
    }
  }

  isValid(instance) {
    // eslint-disable-next-line no-unused-vars
    for (const _error of this.iterErrors(instance)) return false;
    return true;
  }

  *descend(instance, schema, path, resolver) {
    const childResolver = resolver ?? this.resolver.inSubresource(schema);
    for (const error of this.evolve(schema, childResolver).iterErrors(instance)) {
      if (path !== undefined) error.path.unshift(path);
      yield error;
    }
  }

  *validateReference(ref, instance) {
    const resolved = this.resolver.lookup(ref); // Unresolvable propagates
    yield* this.descend(instance, resolved.contents, undefined, resolved.resolver);
  }

  /** Returns None; raises SchemaError on the first meta-schema violation. */
  static checkSchema(schema) {
    const metaValidator = new Draft7Validator(draft7Metaschema(), {
      formatChecker: DRAFT7_FORMAT_CHECKER,
    });
    for (const error of metaValidator.iterErrors(schema)) throw new SchemaError(error);
    return null;
  }
}

