// A hand-rolled stand-in for the `argparse` parser the script builds:
//
//   parser.add_argument('--a', type=str, required=True, help='instance (JSON string)')
//   parser.add_argument('--b', type=str, required=True, help='schema (JSON string)')
//
// Same usage line, same help layout (argparse puts help text at column 14 for
// this set of options), same messages, same exit codes: 0 for --help, 2 for a
// usage error.

import { basename } from 'node:path';

export class ArgparseExit extends Error {
  constructor(code, text, stream) {
    super(text);
    this.name = 'ArgparseExit';
    this.code = code;
    this.text = text;
    this.stream = stream; // 'stdout' | 'stderr'
  }
}

const OPTIONS = [
  { names: ['-h', '--help'], action: 'help', metavar: null, help: 'show this help message and exit' },
  { names: ['--a'], action: 'store', dest: 'a', metavar: 'A', help: 'instance (JSON string)' },
  { names: ['--b'], action: 'store', dest: 'b', metavar: 'B', help: 'schema (JSON string)' },
];

// argparse treats a lone `-1` as a value rather than an option when no option
// string looks like a negative number, which is the case here.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function helpText(prog) {
  const invocations = OPTIONS.map((opt) => (
    opt.metavar === null
      ? opt.names.join(', ')
      : opt.names.map((n) => `${n} ${opt.metavar}`).join(', ')
  ));
  // help_position = min(max(len(invocation)) + indent + 2, 24)
  const maxLen = Math.max(...invocations.map((s) => s.length + 2));
  const helpPos = Math.min(maxLen + 2, 24);

  const lines = [usageLine(prog), '', 'options:'];
  invocations.forEach((invocation, i) => {
    const left = `  ${invocation}`;
    const pad = helpPos - left.length;
    lines.push(pad > 0 ? left + ' '.repeat(pad) + OPTIONS[i].help : `${left}\n${' '.repeat(helpPos)}${OPTIONS[i].help}`);
  });
  return `${lines.join('\n')}\n`;
}

function fail(prog, message) {
  throw new ArgparseExit(2, `${usageLine(prog)}\n${prog}: error: ${message}\n`, 'stderr');
}

function looksLikeOption(token) {
  if (token === undefined) return false;
  if (!token.startsWith('-') || token === '-') return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  return true;
}

/** Resolve an option string, allowing argparse's unambiguous-prefix matching. */
function findOption(name) {
  for (const opt of OPTIONS) if (opt.names.includes(name)) return { opt, exact: true };
  if (!name.startsWith('--')) return null;
  const matches = [];
  for (const opt of OPTIONS) {
    for (const n of opt.names) {
      if (n.startsWith('--') && n.startsWith(name)) matches.push({ opt, name: n });
    }
  }
  const unique = [...new Set(matches.map((m) => m.opt))];
  if (unique.length === 1) return { opt: unique[0], exact: false };
  if (unique.length > 1) return { ambiguous: matches.map((m) => m.name) };
  return null;
}

export function parseArgs(argv, argv0) {
  const prog = basename(argv0 ?? 'test18.mjs');
  const values = { a: undefined, b: undefined };
  const extras = [];
  let onlyPositionals = false;

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (onlyPositionals) { extras.push(token); continue; }
    if (token === '--') { onlyPositionals = true; continue; }

    if (!looksLikeOption(token)) { extras.push(token); continue; }

    let name = token;
    let inlineValue;
    const eq = token.indexOf('=');
    if (token.startsWith('--') && eq !== -1) {
      name = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    const found = findOption(name);
    if (found === null) { extras.push(token); continue; }
    if (found.ambiguous) {
      fail(prog, `ambiguous option: ${name} could match ${found.ambiguous.join(', ')}`);
    }

    const { opt } = found;
    if (opt.action === 'help') {
      throw new ArgparseExit(0, helpText(prog), 'stdout');
    }

    if (inlineValue !== undefined) {
      values[opt.dest] = inlineValue;
      continue;
    }
    const next = argv[i + 1];
    if (next === undefined || looksLikeOption(next)) {
      fail(prog, `argument ${opt.names.join('/')}: expected one argument`);
    }
    values[opt.dest] = next;
    i++;
  }

