    .filter((opt) => opt.action === 'store' && values[opt.dest] === undefined)
    .map((opt) => opt.names[0]);
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  return values;
}

