// One-off repair: strip stray U+2028/U+2029/U+FEFF that ended up inside a
// source comment, and restore the two comment lines they truncated.
import { readFileSync, writeFileSync } from 'node:fs';

const f = '/output/lib/py/pyregex.mjs';
let s = readFileSync(f, 'utf8');

s = s.replace(/[  ﻿]/g, '');
s = s.replace(
  '//       .   Python excludes only \\n; JS also excludes \\r, ,',
  '//       .   Python excludes only \\n; JS also excludes \\r, U+2028 and U+2029',
);
s = s.replace(
  '//       \\s  Python includes \\x1c-\\x1f and \\x85 but not',
  '//       \\s  Python includes \\x1c-\\x1f and \\x85 but not U+FEFF',
);
writeFileSync(f, s);
console.log('repaired');

